<div class="container-fluid px-3 px-lg-4 py-4"><div class="d-flex flex-column flex-lg-row justify-content-between align-items-lg-end gap-3 mb-4"><div><p class="eyebrow mb-2">PURCHASING / DOCUMENTS</p><h1 class="h3 mb-2">{{ $title }}</h1><p class="text-secondary mb-0">ตรวจสอบเอกสารและทำรายการตามสถานะจากหน้ารายละเอียด</p></div>@if(auth()->user()->hasPermission('purchasing.purchase-documents.create'))<a class="btn btn-app-primary" href="{{ route('purchasing.purchase-documents.create',$documentType?['document_type'=>$documentType]:[]) }}"><i class="bx bx-plus me-1" aria-hidden="true"></i>สร้าง{{ $documentType==='CREDIT_NOTE'?'ใบลดหนี้':'ใบตั้งหนี้' }}</a>@endif</div><div class="card border-0 shadow-sm mb-4" id="document-filters"><div class="card-body p-3 p-lg-4"><div class="d-flex justify-content-between align-items-center gap-2 mb-3"><div><h2 class="h5 mb-1">ตัวกรอง{{ $title }}</h2><p class="small text-secondary mb-0">กรองตามวันที่ Supplier และสถานะ</p></div><button type="button" class="btn btn-app-soft js-reset"><i class="bx bx-reset me-1" aria-hidden="true"></i>ล้างตัวกรอง</button></div><div class="row g-3"><div class="col-md-3"><label class="form-label">วันที่เริ่มต้น</label><input id="document-date-from" type="date" class="form-control"></div><div class="col-md-3"><label class="form-label">วันที่สิ้นสุด</label><input id="document-date-to" type="date" class="form-control"></div><div class="col-md-3"><label class="form-label">Supplier</label><select id="document-supplier" class="form-select" data-url="{{ route('purchasing.purchase-documents.supplier-options') }}"></select></div><div class="col-md-3"><label class="form-label">สถานะ</label><select id="document-status" class="form-select"><option value="">ทุกสถานะ</option><option value="DRAFT">ร่าง</option><option value="APPROVED">อนุมัติแล้ว</option><option value="POSTED">ลงบัญชีแล้ว</option><option value="VOID">ยกเลิก</option></select></div></div></div></div><div class="card border-0 shadow-sm"><div class="card-body p-3 p-lg-4"><div class="mb-3"><h2 class="h5 mb-1">รายการ{{ $title }}</h2><p class="small text-secondary mb-0">ใช้การค้นหาในตารางเพื่อค้นหาเลขเอกสาร Supplier และเอกสารต้นทาง</p></div><div class="table-responsive"><table id="purchase-documents-table" class="table table-hover align-middle w-100" data-url="{{ route('purchasing.purchase-documents.data',$documentType?['document_type'=>$documentType]:[]) }}"><thead><tr><th>เลขที่</th><th>ประเภท</th><th>วันที่</th><th>Supplier</th><th>เอกสารต้นทาง</th><th>ครบกำหนด</th><th class="text-end">ยอดรวม</th><th>สถานะ</th><th class="text-end">จัดการ</th></tr></thead></table></div></div></div></div>
