@push('scripts')<script>$(function(){var tableElement=$('#purchase-documents-table'),filters=$('#document-filters'),text=$.fn.dataTable.render.text(),statuses={DRAFT:'app-status-neutral',APPROVED:'app-status-info',POSTED:'app-status-success',VOID:'app-status-danger'};window.erpInitSelect2('#document-supplier',{placeholder:'ค้นหา Supplier',allowClear:true,ajax:{url:$('#document-supplier').data('url'),delay:250,data:function(p){return{q:p.term||'',page:p.page||1};},processResults:function(data){return data;}}});var table=tableElement.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:{url:tableElement.data('url'),data:function(data){data.document_date_from=$('#document-date-from').val();data.document_date_to=$('#document-date-to').val();data.supplier_id=$('#document-supplier').val();data.status=$('#document-status').val();}},order:[[2,'desc']],buttons:[window.erpExcelButton(tableElement)],columns:[{data:'document_number',name:'purchase_documents.document_number',render:function(v,type,row){return type==='display'?'<a class="fw-semibold link-primary" href="'+text.display(row.show_url)+'">'+text.display(v)+'</a>':v;}},{data:'document_type',name:'purchase_documents.document_type',render:function(v,type){return type==='display'?'<span class="badge '+(v==='INVOICE'?'app-status-primary':'app-status-danger')+'">'+(v==='INVOICE'?'ใบตั้งหนี้':'ใบลดหนี้')+'</span>':v;}},{data:'document_date_label',name:'purchase_documents.document_date',render:text.display},{data:'supplier_label',name:'purchase_documents.supplier_code',render:text.display},{data:'original_label',name:'originals.document_number',render:function(v,type,row){return type==='display'&&row.original_url?'<a class="link-primary" href="'+text.display(row.original_url)+'">'+text.display(v)+'</a>':text.display(v);}},{data:'due_date_label',name:'purchase_documents.due_date',render:text.display},{data:'gross_amount',name:'purchase_documents.gross_amount',className:'text-end',render:$.fn.dataTable.render.number(',','.',2)},{data:'status_label',name:'purchase_documents.status',render:function(v,type,row){return type==='display'?'<span class="badge '+(statuses[row.status]||'app-status-neutral')+'">'+text.display(v)+'</span>':row.status;}},{data:null,orderable:false,searchable:false,className:'text-end text-nowrap',render:function(v,type,row){if(type!=='display')return '';var actions=['<a class="btn btn-sm btn-app-soft" href="'+text.display(row.show_url)+'" title="ดูรายละเอียด" aria-label="ดูรายละเอียด"><i class="bx bx-file-find" aria-hidden="true"></i></a>'];if(row.edit_url)actions.push('<a class="btn btn-sm btn-app-soft" href="'+text.display(row.edit_url)+'" title="แก้ไข" aria-label="แก้ไข"><i class="bx bx-edit" aria-hidden="true"></i></a>');if(row.print_url)actions.push('<a class="btn btn-sm btn-app-soft" target="_blank" href="'+text.display(row.print_url)+'" title="พิมพ์" aria-label="พิมพ์"><i class="bx bx-printer" aria-hidden="true"></i></a>');if(row.delete_url)actions.push('<button type="button" class="btn btn-sm btn-app-danger js-delete" data-url="'+text.display(row.delete_url)+'" title="ลบร่าง" aria-label="ลบร่าง"><i class="bx bx-trash" aria-hidden="true"></i></button>');return actions.join(' ');}}]}));filters.on('change','input,select',function(){table.ajax.reload();});filters.on('click','.js-reset',function(){filters.find('input,select').val('');$('#document-supplier').val(null).trigger('change');table.ajax.reload();});window.erpAjaxDelete({button:'.js-delete',reload:'#purchase-documents-table',title:'ลบร่างเอกสารซื้อ?',text:'เอกสารร่างจะถูกลบและไม่สามารถกู้คืนได้',confirmButtonText:'ลบร่าง',cancelButtonText:'กลับ'});});</script>@endpush
